export function SkipLink({
  linkText = "{{linkText}}",
  targetLabel = "{{targetLabel}}",
  reveal = {{reveal}},
  accent = "{{accent}}",
  radius = {{radius}},
}) {
  const hidden = { position: "absolute", left: -9999, top: 0, padding: "10px 16px", background: accent, color: "#FAF7F2", textDecoration: "none", fontWeight: 600, zIndex: 2, borderRadius: radius };
  const shown = { ...hidden, position: "static", left: "auto", display: "inline-block", marginBottom: 8, outline: "2px solid " + accent, outlineOffset: 2 };
  return (
    <div style={{ width: 340, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430", position: "relative" }}>
      <a href="#skip-demo-main-r" style={reveal ? shown : hidden}>{linkText}</a>
      <header style={{ display: "flex", alignItems: "center", gap: 14, flexWrap: "wrap", padding: "10px 12px", borderRadius: 8, background: "#24143010" }}>
        <span style={{ fontWeight: 800 }}>Brand</span>
        <nav style={{ fontSize: 12, color: "#241430aa" }}>Home &middot; Products &middot; About &middot; Contact &middot; Support &middot; Careers</nav>
      </header>
      <main id="skip-demo-main-r" tabIndex={-1} style={{ marginTop: 10, padding: 14, borderRadius: 8, border: "1.5px dashed #24143033" }}>
        <h1 style={{ margin: "0 0 6px", fontSize: 16 }}>{targetLabel}</h1>
        <p style={{ margin: 0, fontSize: 12, color: "#241430aa" }}>Focus lands here, skipping the repeated header links above.</p>
      </main>
      {reveal && <p style={{ marginTop: 8, fontSize: 11, color: "#241430aa" }}>shown as if Tab-focused &mdash; normally clipped off-screen until focus arrives</p>}
    </div>
  );
}
